SET search_path=vcm,pg_catalog;
CREATE TABLE external_links(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),provider text NOT NULL,external_type text NOT NULL,external_id text NOT NULL,sync_status text NOT NULL DEFAULT 'pending' CHECK(sync_status IN('pending','linked','conflict','failed')),field_ownership jsonb NOT NULL DEFAULT '{}',last_synced_at timestamptz,UNIQUE(provider,external_type,external_id));
CREATE TABLE integration_connections(id text PRIMARY KEY,provider text NOT NULL,status text NOT NULL DEFAULT 'unverified' CHECK(status IN('unverified','connected','unavailable','revoked')),capabilities jsonb NOT NULL DEFAULT '[]',secret_reference text,verified_at timestamptz);
CREATE TABLE automation_rules(id text PRIMARY KEY,name text NOT NULL,enabled boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE automation_rule_versions(id text PRIMARY KEY,rule_id text NOT NULL REFERENCES automation_rules(id),version int NOT NULL CHECK(version>0),trigger_type text NOT NULL,conditions jsonb NOT NULL CHECK(jsonb_typeof(conditions)='object'),action_class text NOT NULL,retry_policy jsonb NOT NULL DEFAULT '{"maxAttempts":3}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(rule_id,version));
CREATE TRIGGER automation_revision_immutable BEFORE UPDATE OR DELETE ON automation_rule_versions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE jobs(id text PRIMARY KEY,rule_revision_id text NOT NULL REFERENCES automation_rule_versions(id),case_id text NOT NULL REFERENCES cases(id),mandate_id text REFERENCES operation_mandates(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','blocked','succeeded','failed','cancelled','ambiguous')),next_run_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_owner text,attempt_count int NOT NULL DEFAULT 0 CHECK(attempt_count>=0),max_attempts int NOT NULL DEFAULT 3 CHECK(max_attempts>0),idempotency_key text NOT NULL UNIQUE,blocked_reason text,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'running' OR (lease_until IS NOT NULL AND lease_owner IS NOT NULL)),CHECK(status<>'blocked' OR blocked_reason IS NOT NULL));
CREATE INDEX jobs_due_idx ON jobs(next_run_at,id) WHERE status='pending';
CREATE INDEX jobs_lease_idx ON jobs(lease_until) WHERE status='running';
CREATE TABLE job_attempts(id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(id),attempt int NOT NULL CHECK(attempt>0),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status text NOT NULL CHECK(status IN('running','succeeded','failed','ambiguous')),result jsonb,error_code text,UNIQUE(job_id,attempt));
CREATE TABLE audit_events(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),actor_id text NOT NULL REFERENCES principals(id),acting_service_id text REFERENCES principals(id),action text NOT NULL,reason text NOT NULL,before_data jsonb,after_data jsonb,rule_version text NOT NULL,correlation_id text NOT NULL,at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE INDEX audit_object_time_idx ON audit_events(object_id,at);
CREATE INDEX audit_correlation_idx ON audit_events(correlation_id);
CREATE TABLE outbox_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),event_type text NOT NULL,payload jsonb NOT NULL,correlation_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE INDEX outbox_pending_idx ON outbox_events(sequence) WHERE published_at IS NULL;
CREATE TABLE idempotency_requests(principal_id text NOT NULL REFERENCES principals(id),operation text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb,status_code int,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT(now()+interval '7 days'),PRIMARY KEY(principal_id,operation,key),CHECK(expires_at>created_at));
CREATE TABLE import_batches(id text PRIMARY KEY,source_version int NOT NULL CHECK(source_version BETWEEN 1 AND 4),source_hash text NOT NULL,status text NOT NULL CHECK(status IN('preview','approved','importing','completed','failed')),source_document_id text REFERENCES document_references(id),actor_id text REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_mappings(batch_id text NOT NULL REFERENCES import_batches(id),entity_type text NOT NULL,legacy_id text NOT NULL,internal_id text,demo boolean NOT NULL DEFAULT false,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),PRIMARY KEY(batch_id,entity_type,legacy_id));
CREATE TABLE import_issues(id text PRIMARY KEY,batch_id text NOT NULL,entity_type text NOT NULL,legacy_id text NOT NULL,code text NOT NULL,detail text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved')),resolution text,FOREIGN KEY(batch_id,entity_type,legacy_id) REFERENCES import_mappings(batch_id,entity_type,legacy_id));
-- Runtime is not an owner. DDL and secrets are deliberately absent.
GRANT USAGE ON SCHEMA vcm TO vcm_runtime;
GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA vcm TO vcm_runtime;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA vcm TO vcm_runtime;
REVOKE ALL ON users,sessions,service_credentials,integration_connections FROM vcm_runtime;
-- Credentials require explicit functions/API identity module grants in the API delivery.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['object_revisions','plan_revisions','plan_objectives','objective_cases','work_plan_revisions','decision_revisions','decision_outcomes','approval_records','approval_revocations','field_assertions','field_resolutions','resolution_assertions','evidence_reviews','campaign_revisions','content_revisions','content_assets','package_revisions','package_items','case_snapshots','cut_cases','cut_revisions','report_runs','automation_rule_versions','audit_events'] LOOP EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE ON vcm.%I FROM vcm_runtime',t); END LOOP; END $$;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON roles,state_definitions,transition_definitions,catalog_versions,catalog_entries,field_definitions,indicators,indicator_rule_versions,indicator_targets FROM vcm_runtime;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA vcm FROM PUBLIC;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA vcm TO vcm_runtime;
-- Index every FK unless already covered by a matching index prefix.
DO $$ DECLARE r record; BEGIN FOR r IN SELECT c.conrelid, c.conname, string_agg(quote_ident(a.attname),',' ORDER BY u.ord) cols FROM pg_constraint c CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY u(attnum,ord) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=u.attnum WHERE c.contype='f' AND c.connamespace='vcm'::regnamespace AND NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid=c.conrelid AND (i.indkey::smallint[])[0:cardinality(c.conkey)-1]=c.conkey) GROUP BY c.conrelid,c.conname LOOP EXECUTE format('CREATE INDEX %I ON %s (%s)',left(r.conname,54)||'_fkidx',r.conrelid::regclass,r.cols); END LOOP; END $$;
